final com.android.server.provguard.ProvGuardInternal pgInternal =
        com.android.server.LocalServices.getService(com.android.server.provguard.ProvGuardInternal.class);
if (pgInternal != null) {
    pgInternal.registerWindowLockVerifier((token, expectedUid, checkCoords, x, y) -> {
        synchronized (mGlobalLock) {
            final WindowState target = mWindowMap.get(token);
            if (target == null || !target.isVisible() || target.getOwningUid() != expectedUid) {
                return false;
            }
            if (checkCoords) {
                final DisplayContent dc = target.getDisplayContent();
                final WindowState top = dc != null ? dc.getTouchableWinAtPointLocked(x, y) : null;
                if (top == null || top.mClient.asBinder() != token) {
                    return false;
                }
            }
            return true;
        }
    });
}

