// ProvGuard Assumption 7: verify expected node digest in target window before executing action
final android.os.Bundle pgArgs = (android.os.Bundle) args.arg1;
if (pgArgs != null && pgArgs.containsKey("provguard_expected_digest")) {
    final String expectedDigest = pgArgs.getString("provguard_expected_digest");
    final View pgTarget = findViewByAccessibilityId(args.argi1);
    if (pgTarget == null) {
        return;
    }
    final android.graphics.Rect pgRect = new android.graphics.Rect();
    pgTarget.getBoundsOnScreen(pgRect);
    final String liveDigest = android.security.provguard.ProvGuardDigest.computeNodeDigest(
            pgTarget.getAccessibilityClassName() != null ? pgTarget.getAccessibilityClassName().toString() : "",
            pgTarget instanceof android.widget.TextView ? String.valueOf(((android.widget.TextView) pgTarget).getText()) : "",
            pgTarget.getContentDescription() != null ? pgTarget.getContentDescription().toString() : "",
            pgTarget.getId() != View.NO_ID ? String.valueOf(pgTarget.getId()) : "",
            pgRect.left, pgRect.top, pgRect.right, pgRect.bottom);
    if (!liveDigest.equals(expectedDigest)) {
        android.util.Log.w("ProvGuardBinder", "Rejecting a11y action: live node digest mismatch");
        return;
    }
}

